={{ (function() {
  try {
    const input = $("Aggregate").item.json.data;
    if (!input || !Array.isArray(input)) return "⚠️ Данные не найдены";

    const treatment = input.filter(i => i['Тип'] === 'лечение');
    const check = input.filter(i => i['Тип'] === 'проверка');

    let message = "📋 **ЕЖЕДНЕВНЫЙ ОТЧЕТ ПО МЕДУХОДУ**\n\n";

    if (treatment.length > 0) {
      message += "💊 **ТЕКУЩЕЕ ЛЕЧЕНИЕ:**\n";
      message += treatment.map(item => {
        const cat = item['cat_number_txt'] || '---';
        const room = Array.isArray(item['Комната']) ? item['Комната'][0] : (item['Комната'] || '---');
        const med = Array.isArray(item['Name (from Лекарство+срок годности)']) ? item['Name (from Лекарство+срок годности)'][0] : (item['med_txt'] || 'манипуляция');
        const loc = Array.isArray(item['Med_location']) ? item['Med_location'][0] : '---';

        // .trim() убирает лишние переносы из самой базы данных
        const log = (item['Коммент (общий)'] || '-').toString().trim();
        const dateEnd = item['Дата окончания приема'] || '---';

        return `\n🐱 **Кошка:** ${cat} (комн. ${room})\n` +
               `💊 **Лекарство:** ${med}\n` +
               `📦 **Расположение:** ${loc}\n` +
               `💬 **Коммент:** ${log}\n` +
               `⌛ **Окончание:** ${dateEnd}\n` +
               `──────────────────`;
      }).join('\n'); // Соединяем записи без лишних пустых строк
    }

    if (check.length > 0) {
      if (treatment.length > 0) message += "\n\n"; // Отступ только между блоками
      const catNumbers = check.map(item => {
        const num = item['cat_number_txt'];
        return Array.isArray(num) ? num[0] : num;
      }).filter(n => n).join(', ');

      if (catNumbers) message += `🧵 **ПРОВЕРКА ШВОВ (номера):**\n${catNumbers}`;
    }

    return message;
  } catch (e) {
    return "❌ Ошибка: " + e.message;
  }
})() }}

